def _digits_to_int(s: str):
    n = len(s)
    if n == 0:
        return 0

    chunks = []
    first = n % 9

    if first:
        chunks.append(int(s[:first]))
        start = first
    else:
        start = 0

    while start < n:
        chunks.append(int(s[start:start + 9]))
        start += 9

